function sumPositives(nums) {
  let sum = 0;
  let i = 0;
  while (i < nums.length) {
    if (nums[i] > 0) {
      sum += nums[i];
    }
    i++;
  }
  return sum;
}
console.log(sumPositives([3, -1, 4]));

